class Solution {
public:
    long long countPairs(vector<int>& nums, int k) {
        unordered_map<int, int> gcdCnt;
        for (int x : nums) gcdCnt[gcd(x, k)]++;
        vector<pair<int, int>> divs(gcdCnt.begin(), gcdCnt.end());
        long long ans = 0;
        int m = divs.size();
        for (int i = 0; i < m; i++) {
            long long d1 = divs[i].first, c1 = divs[i].second;
            if ((d1 * d1) % k == 0) {
                ans += c1 * (c1 - 1) / 2;
            }
            for (int j = i + 1; j < m; j++) {
                long long d2 = divs[j].first, c2 = divs[j].second;
                if ((d1 * d2) % k == 0) {
                    ans += c1 * c2;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long countPairs(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) {
            int g = gcd(x, k);
            map.put(g, map.getOrDefault(g, 0) + 1);
        }
        List<Integer> keys = new ArrayList<>(map.keySet());
        long ans = 0;
        int m = keys.size();
        for (int i = 0; i < m; i++) {
            long d1 = keys.get(i);
            long c1 = map.get((int) d1);
            if ((d1 * d1) % k == 0) {
                ans += c1 * (c1 - 1) / 2;
            }
            for (int j = i + 1; j < m; j++) {
                long d2 = keys.get(j);
                long c2 = map.get((int) d2);
                if ((d1 * d2) % k == 0) {
                    ans += c1 * c2;
                }
            }
        }
        return ans;
    }
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

var countPairs = function(nums, k) {
    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    const map = new Map();
    for (const x of nums) {
        const g = gcd(x, k);
        map.set(g, (map.get(g) || 0) + 1);
    }
    const keys = Array.from(map.keys());
    let ans = 0n;
    const bigK = BigInt(k);
    for (let i = 0; i < keys.length; i++) {
        const d1 = BigInt(keys[i]);
        const c1 = BigInt(map.get(keys[i]));
        if ((d1 * d1) % bigK === 0n) {
            ans += c1 * (c1 - 1n) / 2n;
        }
        for (let j = i + 1; j < keys.length; j++) {
            const d2 = BigInt(keys[j]);
            const c2 = BigInt(map.get(keys[j]));
            if ((d1 * d2) % bigK === 0n) {
                ans += c1 * c2;
            }
        }
    }
    return Number(ans);
};
